package dev.shadw.khemet.mobs;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the Mummy with its own model and texture. Generated by shadw-mod mob. */
public class MummyRenderer extends MobRenderer<Mummy, MummyModel.State, MummyModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("khemet", "textures/entity/mummy.png");

	public MummyRenderer(EntityRendererProvider.Context context) {
		super(context, new MummyModel(context.bakeLayer(MummyModel.LAYER)), 0.5F);
	}

	@Override
	public MummyModel.State createRenderState() {
		return new MummyModel.State();
	}

	@Override
	public void extractRenderState(Mummy entity, MummyModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
		state.airborne = !entity.onGround() && !entity.isNoAi();        // a mob with its AI off is posed, not flying
	}

	@Override
	public ResourceLocation getTextureLocation(MummyModel.State state) {
		return TEXTURE;
	}
}
